#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n); /* 1. Leer cuántos datos vienen */
    double x, suma = 0.0; /* 2. El acumulador empieza en cero */
    for (int i = 0; i < n; i++) { /* 3. Repetir n veces: leer y acumular */
        scanf("%lf", &x);
        suma += x;
    }
    printf("%.2f\n", suma / n); /* 4. Dividir entre n e imprimir */
    return 0;
}

