#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    double x, mayor;
    scanf("%lf", &mayor);
    for (int i = 1; i < n; i++) {
        scanf("%lf", &x);
        if (x > mayor) mayor = x;
    }
    printf("%.1f\n", mayor);
    return 0;
}

